#!/usr/bin/env python3
"""Refine cell annotations with MobileSAM and write polygon contours."""

import argparse
import csv
import os
import re

import cv2
import numpy as np
import torch
from mobile_sam import SamPredictor, sam_model_registry


REQUIRED_COLUMNS = (
    "xmin",
    "xmax",
    "ymin",
    "ymax",
    "coords_x",
    "coords_y",
)


def parse_args():
    parser = argparse.ArgumentParser(
        description="Convert cell masks in a CSV to MobileSAM-refined polylines."
    )
    parser.add_argument("--weights_path", type=str, required=True)
    parser.add_argument("--output_path", type=str, required=True)
    parser.add_argument("--rgb_path", type=str, required=True)
    parser.add_argument("--csv_path", type=str, required=True)
    return parser.parse_args()


def parse_coordinate_list(value):
    """Parse comma-, whitespace-, or semicolon-separated coordinates."""
    if value is None:
        return np.empty(0, dtype=np.float32)
    text = str(value).strip()
    if not text:
        return np.empty(0, dtype=np.float32)
    text = text.strip("[]()")
    tokens = [token for token in re.split(r"[,;\s]+", text) if token]
    try:
        return np.asarray([float(token) for token in tokens], dtype=np.float32)
    except ValueError as exc:
        raise ValueError("Could not parse a coordinate list: %r" % value) from exc


def read_metadata(csv_path):
    with open(csv_path, "r", newline="") as csv_file:
        reader = csv.DictReader(csv_file)
        if reader.fieldnames is None:
            raise ValueError("The metadata CSV has no header: %s" % csv_path)
        missing = [column for column in REQUIRED_COLUMNS if column not in reader.fieldnames]
        if missing:
            raise ValueError("The metadata CSV is missing columns: %s" % ", ".join(missing))
        rows = list(reader)
    if not rows:
        raise ValueError("The metadata CSV contains no mask rows: %s" % csv_path)
    return reader.fieldnames, rows


def integer_box(row, width, height):
    try:
        x0 = float(row["xmin"])
        x1 = float(row["xmax"])
        y0 = float(row["ymin"])
        y1 = float(row["ymax"])
    except (TypeError, ValueError) as exc:
        raise ValueError("A bounding box contains a non-numeric value: %r" % row) from exc

    x0, x1 = sorted((int(round(x0)), int(round(x1))))
    y0, y1 = sorted((int(round(y0)), int(round(y1))))
    x0 = min(max(x0, 0), width - 1)
    x1 = min(max(x1, 0), width - 1)
    y0 = min(max(y0, 0), height - 1)
    y1 = min(max(y1, 0), height - 1)
    return x0, y0, x1, y1


def source_mask(row, width, height, box):
    x_values = parse_coordinate_list(row["coords_x"])
    y_values = parse_coordinate_list(row["coords_y"])
    if len(x_values) != len(y_values):
        raise ValueError("coords_x and coords_y have different lengths in row: %r" % row)

    mask = np.zeros((height, width), dtype=np.uint8)
    if len(x_values) >= 3:
        points = np.column_stack((x_values, y_values))
        points = np.rint(points).astype(np.int32)
        points[:, 0] = np.clip(points[:, 0], 0, width - 1)
        points[:, 1] = np.clip(points[:, 1], 0, height - 1)
        cv2.fillPoly(mask, [points.reshape((-1, 1, 2))], 1)

    if not np.any(mask):
        x0, y0, x1, y1 = box
        cv2.rectangle(mask, (x0, y0), (x1, y1), 1, thickness=-1)
    return mask.astype(bool)


def interior_point(mask, box):
    mask_uint8 = mask.astype(np.uint8)
    distances = cv2.distanceTransform(mask_uint8, cv2.DIST_L2, 5)
    _, maximum, _, maximum_location = cv2.minMaxLoc(distances)
    if maximum > 0:
        x, y = maximum_location
        return int(x), int(y)

    ys, xs = np.where(mask)
    if len(xs):
        middle = len(xs) // 2
        return int(xs[middle]), int(ys[middle])

    x0, y0, x1, y1 = box
    return (x0 + x1) // 2, (y0 + y1) // 2


def connected_component(mask, point=None):
    """Return one connected component, preferring the component at point."""
    mask_uint8 = mask.astype(np.uint8)
    if not np.any(mask_uint8):
        return np.zeros_like(mask, dtype=bool)

    count, labels, stats, _ = cv2.connectedComponentsWithStats(mask_uint8, 8)
    chosen_label = 0
    if point is not None:
        x, y = point
        if 0 <= y < labels.shape[0] and 0 <= x < labels.shape[1]:
            chosen_label = int(labels[y, x])

    if chosen_label == 0:
        areas = stats[1:, cv2.CC_STAT_AREA]
        chosen_label = 1 + int(np.argmax(areas))
    return labels == chosen_label


def mask_iou(first, second):
    intersection = np.count_nonzero(first & second)
    union = np.count_nonzero(first | second)
    return float(intersection) / float(union) if union else 0.0


def resize_mask(mask, height, width):
    if mask.shape == (height, width):
        return mask.astype(bool)
    resized = cv2.resize(
        mask.astype(np.uint8), (width, height), interpolation=cv2.INTER_NEAREST
    )
    return resized.astype(bool)


def choose_prediction(predicted_masks, scores, source, point):
    """Choose the SAM candidate aligned with the input annotation."""
    height, width = source.shape
    masks = np.asarray(predicted_masks)
    if masks.ndim == 2:
        masks = masks[None, ...]
    if masks.ndim != 3:
        raise ValueError("MobileSAM returned masks with an unexpected shape: %r" % (masks.shape,))

    score_values = np.asarray(scores).reshape(-1) if scores is not None else np.zeros(len(masks))
    candidates = []
    for index, predicted in enumerate(masks):
        candidate = resize_mask(predicted, height, width)
        candidate = connected_component(candidate, point)
        if not np.any(candidate):
            continue
        quality = float(score_values[index]) if index < len(score_values) else 0.0
        overlap = mask_iou(candidate, source)
        contains_point = bool(candidate[point[1], point[0]])
        rank = (int(contains_point), 0.65 * overlap + 0.35 * quality, overlap, quality)
        candidates.append((rank, candidate))

    if not candidates:
        return source.copy()
    candidates.sort(key=lambda item: item[0], reverse=True)
    return candidates[0][1]


def polygon_from_mask(mask):
    """Convert one connected binary mask to a closed integer contour."""
    contours, _ = cv2.findContours(
        mask.astype(np.uint8), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE
    )
    if not contours:
        return np.empty((0, 2), dtype=np.int32)
    contour = max(contours, key=cv2.contourArea).reshape((-1, 2)).astype(np.int32)

    if len(contour) == 1:
        x, y = contour[0]
        contour = np.asarray([[x, y], [x + 1, y], [x, y + 1]], dtype=np.int32)
    elif len(contour) == 2:
        x0, y0 = contour[0]
        x1, y1 = contour[1]
        contour = np.asarray(
            [[x0, y0], [x1, y1], [x0, y1]], dtype=np.int32
        )

    if not np.array_equal(contour[0], contour[-1]):
        contour = np.vstack((contour, contour[0]))
    return contour


def update_row(row, mask):
    ys, xs = np.where(mask)
    if not len(xs):
        raise ValueError("A mask became empty while resolving overlaps")

    contour = polygon_from_mask(mask)
    if len(contour) == 0:
        raise ValueError("Could not extract a contour from a non-empty mask")

    row["xmin"] = str(int(xs.min()))
    row["xmax"] = str(int(xs.max()))
    row["ymin"] = str(int(ys.min()))
    row["ymax"] = str(int(ys.max()))
    row["coords_x"] = ",".join(str(int(value)) for value in contour[:, 0])
    row["coords_y"] = ",".join(str(int(value)) for value in contour[:, 1])


def load_mobile_sam(weights_path, device):
    """Load the MobileSAM TinyViT checkpoint in a device-safe way."""
    model = sam_model_registry["vit_t"](checkpoint=None)
    checkpoint = torch.load(weights_path, map_location="cpu")

    if isinstance(checkpoint, torch.nn.Module):
        state_dict = checkpoint.state_dict()
    elif isinstance(checkpoint, dict):
        state_dict = checkpoint
        for key in ("state_dict", "model_state_dict", "model"):
            if key in state_dict and isinstance(state_dict[key], dict):
                state_dict = state_dict[key]
                break
    else:
        raise ValueError("The MobileSAM weights file does not contain a state dict")

    if state_dict and all(str(key).startswith("module.") for key in state_dict):
        state_dict = {str(key)[len("module."):]: value for key, value in state_dict.items()}
    model.load_state_dict(state_dict)
    model.to(device=device)
    model.eval()
    return model


def convert_masks(weights_path, output_path, rgb_path, csv_path):
    image_bgr = cv2.imread(rgb_path, cv2.IMREAD_COLOR)
    if image_bgr is None:
        raise FileNotFoundError("Could not read RGB image: %s" % rgb_path)
    image = cv2.cvtColor(image_bgr, cv2.COLOR_BGR2RGB)
    height, width = image.shape[:2]

    fieldnames, rows = read_metadata(csv_path)
    records = []
    for index, row in enumerate(rows):
        box = integer_box(row, width, height)
        source = source_mask(row, width, height, box)
        point = interior_point(source, box)
        records.append(
            {
                "index": index,
                "row": row,
                "box": box,
                "source": source,
                "point": point,
                "area": int(np.count_nonzero(source)),
            }
        )

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    model = load_mobile_sam(weights_path, device)
    predictor = SamPredictor(model)
    predictor.set_image(image)

    # Smaller annotations claim shared pixels first, which prevents a broad
    # prediction from consuming a neighboring small cell.
    records_by_area = sorted(records, key=lambda item: (item["area"], item["index"]))
    occupied = np.zeros((height, width), dtype=bool)
    refined_masks = [None] * len(records)

    for record in records_by_area:
        x0, y0, x1, y1 = record["box"]
        point = record["point"]
        point_coords = np.asarray([[point[0], point[1]]], dtype=np.float32)
        point_labels = np.asarray([1], dtype=np.int32)
        box = np.asarray([x0, y0, x1, y1], dtype=np.float32)

        with torch.no_grad():
            predicted_masks, scores, _ = predictor.predict(
                point_coords=point_coords,
                point_labels=point_labels,
                box=box,
                multimask_output=True,
            )

        candidate = choose_prediction(predicted_masks, scores, record["source"], point)
        available = candidate & ~occupied
        selected = connected_component(available, point)

        if not np.any(selected):
            # This is only needed when a prediction is completely covered by a
            # previously accepted mask. The original annotation is a safer
            # fallback than returning an empty cell.
            fallback = record["source"] & ~occupied
            selected = connected_component(fallback, point)

        if not np.any(selected):
            raise ValueError(
                "Could not retain a non-overlapping mask for metadata row %d" % record["index"]
            )

        occupied |= selected
        refined_masks[record["index"]] = selected

    for row, mask in zip(rows, refined_masks):
        update_row(row, mask)

    output_directory = os.path.dirname(os.path.abspath(output_path))
    if output_directory:
        os.makedirs(output_directory, exist_ok=True)
    with open(output_path, "w", newline="") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(rows)


def main():
    args = parse_args()
    convert_masks(args.weights_path, args.output_path, args.rgb_path, args.csv_path)


if __name__ == "__main__":
    main()
